2	
3	import type { AgentState } from "@/components/ui/orb";
4	import type { AgentState as BarState } from "@/components/ui/bar-visualizer";
5	
6	export type CallState = "idle" | "connecting" | "listening" | "speaking" | "interrupted" | "ended";
7	
8	export interface SessionTurn {
9	  id: string;
10	  who: "agent" | "user";
11	  text: string;
12	  live?: boolean;
13	}
14	
15	// The unified surface every provider exposes to the UI. The UI never talks to a
16	// provider directly — it binds to this, and the active provider is swapped
17	// behind it (mock for the design's fake lifecycle, ElevenLabs for the real one).
18	export interface SessionApi {
19	  callState: CallState;
20	  turns: SessionTurn[];
21	  caption: string;
22	  muted: boolean;
23	  elapsed: number;
24	  isReal: boolean;
25	  toggleMute: () => void;
26	  start: () => void;
27	  hangup: () => void;
28	  interrupt: () => void;
29	  getInputVolume: () => number;
30	  getOutputVolume: () => number;
31	}
32	
33	export const STATE_LABEL: Record<CallState, string> = {
34	  idle: "IDLE",
35	  connecting: "CONNECTING",
36	  listening: "LISTENING",
37	  speaking: "SPEAKING",
38	  interrupted: "INTERRUPTED",
39	  ended: "ENDED",
40	};
41	
42	export function isLive(s: CallState): boolean {
43	  return s !== "idle" && s !== "ended";
44	}
45	
46	// CallState → ElevenLabs WebGL Orb agentState.
47	export function toOrbState(s: CallState): AgentState {
48	  switch (s) {
49	    case "speaking":
50	      return "talking";
51	    case "listening":
52	    case "interrupted":
53	      return "listening";
54	    case "connecting":
55	      return "thinking";
56	    default:
57	      return null;
58	  }
59	}
60	
61	// CallState → BarVisualizer state.
62	export function toBarState(s: CallState): BarState {
63	  switch (s) {
64	    case "speaking":
65	      return "speaking";
66	    case "connecting":
67	      return "connecting";
68	    case "interrupted":
69	    case "listening":
70	      return "listening";
71	    default:
72	      return "initializing";
73	  }
74	}
