1	/**
2	 * Audio utilities for WebRTC capture and playback
3	 */
4	
5	const SAMPLE_RATE = 24000;
6	// const CHUNK_DURATION_MS = 100;
7	// Chunk size calculation (currently unused but may be needed later)
8	// const CHUNK_SIZE_SAMPLES = (SAMPLE_RATE * CHUNK_DURATION_MS) / 1000;
9	
10	/**
11	 * Convert Float32Array to PCM16 and base64 encode
12	 */
13	export function float32ToPCM16Base64(float32Array: Float32Array): string {
14	  const pcm16 = new Int16Array(float32Array.length);
15	  for (let i = 0; i < float32Array.length; i++) {
16	    const s = Math.max(-1, Math.min(1, float32Array[i]));
17	    pcm16[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
18	  }
19	  return arrayBufferToBase64(pcm16.buffer);
20	}
21	
22	/**
23	 * Convert base64 PCM16 to Float32Array for playback
24	 */
25	export function base64PCM16ToFloat32(base64: string): Float32Array {
26	  const binary = atob(base64);
27	  const bytes = new Uint8Array(binary.length);
28	  for (let i = 0; i < binary.length; i++) {
29	    bytes[i] = binary.charCodeAt(i);
30	  }
31	  const pcm16 = new Int16Array(bytes.buffer);
32	  const float32 = new Float32Array(pcm16.length);
33	  for (let i = 0; i < pcm16.length; i++) {
34	    float32[i] = pcm16[i] / (pcm16[i] < 0 ? 0x8000 : 0x7fff);
35	  }
36	  return float32;
37	}
38	
39	/**
40	 * Convert ArrayBuffer to base64
41	 */
42	function arrayBufferToBase64(buffer: ArrayBuffer): string {
43	  const bytes = new Uint8Array(buffer);
44	  let binary = "";
45	  for (let i = 0; i < bytes.byteLength; i++) {
46	    binary += String.fromCharCode(bytes[i]);
47	  }
48	  return btoa(binary);
49	}
50	
51	/**
52	 * Resample audio from source sample rate to 24kHz
53	 */
54	export function resampleTo24kHz(
55	  audioBuffer: AudioBuffer,
56	  targetSampleRate: number = SAMPLE_RATE
57	): Float32Array {
58	  const sourceRate = audioBuffer.sampleRate;
59	  const sourceData = audioBuffer.getChannelData(0);
60	
61	  if (sourceRate === targetSampleRate) {
62	    return sourceData;
63	  }
64	
65	  const ratio = sourceRate / targetSampleRate;
66	  const targetLength = Math.round(sourceData.length / ratio);
67	  const resampled = new Float32Array(targetLength);
68	
69	  for (let i = 0; i < targetLength; i++) {
70	    const sourceIndex = i * ratio;
71	    const index = Math.floor(sourceIndex);
72	    const fraction = sourceIndex - index;
73	
74	    if (index + 1 < sourceData.length) {
75	      // Linear interpolation
76	      resampled[i] = sourceData[index] * (1 - fraction) + sourceData[index + 1] * fraction;
77	    } else {
78	      resampled[i] = sourceData[index];
79	    }
80	  }
81	
82	  return resampled;
83	}
84	
85	/**
86	 * Calculate RMS (Root Mean Square) audio level
87	 */
88	export function calculateRMS(float32Array: Float32Array): number {
89	  let sum = 0;
90	  for (let i = 0; i < float32Array.length; i++) {
91	    sum += float32Array[i] * float32Array[i];
92	  }
93	  return Math.sqrt(sum / float32Array.length);
94	}
95	
96	/**
97	 * Get audio level in decibels
98	 */
99	export function getRMSdB(float32Array: Float32Array): number {
100	  const rms = calculateRMS(float32Array);
101	  return 20 * Math.log10(rms);
102	}
