1	/**
2	 * Audio capture and playback hook using Web Audio API
3	 */
4	
5	import { useEffect, useRef, useState, useCallback } from "react";
6	import { float32ToPCM16Base64, base64PCM16ToFloat32 } from "../utils/audio";
7	
8	const CHUNK_DURATION_MS = 100;
9	
10	interface UseAudioStreamReturn {
11	  isCapturing: boolean;
12	  startCapture: (onAudioData: (base64Audio: string) => void) => Promise<number>;
13	  stopCapture: () => void;
14	  stopPlayback: () => void;
15	  playAudio: (base64Audio: string) => void;
16	  audioLevel: number;
17	  sampleRate: number;
18	}
19	
20	export function useAudioStream(): UseAudioStreamReturn {
21	  const [isCapturing, setIsCapturing] = useState(false);
22	  const [audioLevel, setAudioLevel] = useState(0);
23	  const [sampleRate, setSampleRate] = useState(0);
24	  
25	  const audioContextRef = useRef<AudioContext | null>(null);
26	  const mediaStreamRef = useRef<MediaStream | null>(null);
27	  const sourceNodeRef = useRef<MediaStreamAudioSourceNode | null>(null);
28	  const processorNodeRef = useRef<ScriptProcessorNode | null>(null);
29	  const playbackQueueRef = useRef<Float32Array[]>([]);
30	  const isPlayingRef = useRef(false);
31	  const currentPlaybackSourceRef = useRef<AudioBufferSourceNode | null>(null);
32	
33	  // Initialize audio context with native sample rate
34	  const getAudioContext = useCallback(() => {
35	    if (!audioContextRef.current) {
36	      // Let browser choose native sample rate for optimal performance
37	      audioContextRef.current = new AudioContext();
38	      const nativeSampleRate = audioContextRef.current.sampleRate;
39	      setSampleRate(nativeSampleRate);
40	      console.log(`Audio context initialized with native sample rate: ${nativeSampleRate}Hz`);
41	    }
42	    return audioContextRef.current;
43	  }, []);
44	
45	  // Start audio capture - returns the detected sample rate
46	  const startCapture = useCallback(async (onAudioData: (base64Audio: string) => void): Promise<number> => {
47	    try {
48	      // Initialize audio context first to get native sample rate
49	      const audioContext = getAudioContext();
50	      const nativeSampleRate = audioContext.sampleRate;
51	      
52	      // Request microphone access with native sample rate
53	      const stream = await navigator.mediaDevices.getUserMedia({
54	        audio: {
55	          sampleRate: nativeSampleRate,
56	          channelCount: 1,
57	          echoCancellation: true,
58	          noiseSuppression: true,
59	          autoGainControl: true,
60	        },
61	      });
62	
63	      mediaStreamRef.current = stream;
64	      
65	      // Resume context if suspended
66	      if (audioContext.state === "suspended") {
67	        await audioContext.resume();
68	      }
69	
70	      // Create source from microphone
71	      const source = audioContext.createMediaStreamSource(stream);
72	      sourceNodeRef.current = source;
73	
74	      // Create script processor for audio chunks
75	      const bufferSize = 4096;
76	      const processor = audioContext.createScriptProcessor(bufferSize, 1, 1);
77	      
78	      let audioBuffer: Float32Array[] = [];
79	      let totalSamples = 0;
80	      const chunkSizeSamples = (nativeSampleRate * CHUNK_DURATION_MS) / 1000;
81	
82	      processor.onaudioprocess = (event) => {
83	        const inputData = event.inputBuffer.getChannelData(0);
84	        
85	        // Calculate audio level
86	        let sum = 0;
87	        for (let i = 0; i < inputData.length; i++) {
88	          sum += inputData[i] * inputData[i];
89	        }
90	        const rms = Math.sqrt(sum / inputData.length);
91	        setAudioLevel(rms);
92	
93	        // Buffer audio data
94	        audioBuffer.push(new Float32Array(inputData));
95	        totalSamples += inputData.length;
96	
97	        // Send chunks of ~100ms
98	        while (totalSamples >= chunkSizeSamples) {
99	          const chunk = new Float32Array(chunkSizeSamples);
100	          let offset = 0;
101	
102	          while (offset < chunkSizeSamples && audioBuffer.length > 0) {
103	            const buffer = audioBuffer[0];
104	            const needed = chunkSizeSamples - offset;
105	            const available = buffer.length;
106	
107	            if (available <= needed) {
108	              // Use entire buffer
109	              chunk.set(buffer, offset);
110	              offset += available;
111	              totalSamples -= available;
112	              audioBuffer.shift();
113	            } else {
114	              // Use part of buffer
115	              chunk.set(buffer.subarray(0, needed), offset);
116	              audioBuffer[0] = buffer.subarray(needed);
117	              offset += needed;
118	              totalSamples -= needed;
119	            }
120	          }
121	
122	          // Convert to PCM16 and send
123	          const base64Audio = float32ToPCM16Base64(chunk);
124	          onAudioData(base64Audio);
125	        }
126	      };
127	
128	      processorNodeRef.current = processor;
129	
130	      // Connect nodes
131	      source.connect(processor);
132	      processor.connect(audioContext.destination);
133	
134	      setIsCapturing(true);
135	      console.log(`Audio capture started at ${nativeSampleRate}Hz (native)`);
136	      
137	      // Return the sample rate for immediate use
138	      return nativeSampleRate;
139	    } catch (error) {
140	      console.error("Failed to start audio capture:", error);
141	      throw error;
142	    }
143	  }, [getAudioContext]);
144	
145	  // Stop audio capture
146	  const stopCapture = useCallback(() => {
147	    if (processorNodeRef.current) {
148	      processorNodeRef.current.disconnect();
149	      processorNodeRef.current = null;
150	    }
151	
152	    if (sourceNodeRef.current) {
153	      sourceNodeRef.current.disconnect();
154	      sourceNodeRef.current = null;
155	    }
156	
157	    if (mediaStreamRef.current) {
158	      mediaStreamRef.current.getTracks().forEach((track) => track.stop());
159	      mediaStreamRef.current = null;
160	    }
161	
162	    setIsCapturing(false);
163	    setAudioLevel(0);
164	    console.log("Audio capture stopped");
165	  }, []);
166	
167	  // Stop audio playback
168	  const stopPlayback = useCallback(() => {
169	    // Stop currently playing audio source
170	    if (currentPlaybackSourceRef.current) {
171	      try {
172	        currentPlaybackSourceRef.current.stop();
173	        currentPlaybackSourceRef.current.disconnect();
174	      } catch (error) {
175	        // Source may already be stopped, ignore error
176	      }
177	      currentPlaybackSourceRef.current = null;
178	    }
179	    
180	    // Clear the playback queue
181	    playbackQueueRef.current = [];
182	    isPlayingRef.current = false;
183	    console.log("Audio playback stopped (interrupted)");
184	  }, []);
185	
186	  // Play audio
187	  const playAudio = useCallback((base64Audio: string) => {
188	    try {
189	      const audioContext = getAudioContext();
190	      const float32Data = base64PCM16ToFloat32(base64Audio);
191	      
192	      console.log(`[Playback] Queueing audio chunk: ${float32Data.length} samples at ${audioContext.sampleRate}Hz`);
193	      
194	      // Add to playback queue
195	      playbackQueueRef.current.push(float32Data);
196	
197	      // Start playback if not already playing
198	      if (!isPlayingRef.current) {
199	        isPlayingRef.current = true;
200	        playNextChunk(audioContext);
201	      }
202	    } catch (error) {
203	      console.error("Error playing audio:", error);
204	    }
205	  }, [getAudioContext]);
206	
207	  // Play next chunk from queue
208	  const playNextChunk = useCallback((audioContext: AudioContext) => {
209	    if (playbackQueueRef.current.length === 0) {
210	      isPlayingRef.current = false;
211	      currentPlaybackSourceRef.current = null;
212	      return;
213	    }
214	
215	    const chunk = playbackQueueRef.current.shift()!;
216	    // Use native sample rate for playback (no resampling needed)
217	    const audioBuffer = audioContext.createBuffer(1, chunk.length, audioContext.sampleRate);
218	    audioBuffer.getChannelData(0).set(chunk);
219	    
220	    console.log(`[Playback] Playing chunk: ${chunk.length} samples at ${audioContext.sampleRate}Hz, duration: ${(chunk.length / audioContext.sampleRate * 1000).toFixed(1)}ms`);
221	
222	    const source = audioContext.createBufferSource();
223	    source.buffer = audioBuffer;
224	    source.connect(audioContext.destination);
225	
226	    // Store reference to current source for interruption handling
227	    currentPlaybackSourceRef.current = source;
228	
229	    source.onended = () => {
230	      // Clear reference when playback ends naturally
231	      if (currentPlaybackSourceRef.current === source) {
232	        currentPlaybackSourceRef.current = null;
233	      }
234	      playNextChunk(audioContext);
235	    };
236	
237	    source.start();
238	  }, []);
239	
240	  // Cleanup on unmount
241	  useEffect(() => {
242	    return () => {
243	      stopCapture();
244	      if (audioContextRef.current) {
245	        audioContextRef.current.close();
246	      }
247	    };
248	  }, [stopCapture]);
249	
250	  return {
251	    isCapturing,
252	    startCapture,
253	    stopCapture,
254	    stopPlayback,
255	    playAudio,
256	    audioLevel,
257	    sampleRate,
258	  };
259	}
