1	/**
2	 * XAI API WebSocket client
3	 * Handles communication with XAI's realtime voice API
4	 */
5	
6	import WebSocket from "ws";
7	import type { XAIMessage } from "./types";
8	
9	export interface XAIClientConfig {
10	  apiKey: string;
11	  apiUrl: string;
12	  voice: string;
13	  instructions: string;
14	  sessionId: string;
15	  sampleRate: number;
16	}
17	
18	export type XAIMessageHandler = (message: XAIMessage) => void;
19	export type XAIErrorHandler = (error: Error) => void;
20	export type XAICloseHandler = (code: number, reason: string) => void;
21	export type XAIReadyHandler = () => void;
22	
23	export class XAIClient {
24	  private ws: WebSocket | null = null;
25	  private config: XAIClientConfig;
26	  private messageHandler: XAIMessageHandler | null = null;
27	  private errorHandler: XAIErrorHandler | null = null;
28	  private closeHandler: XAICloseHandler | null = null;
29	  private onReady: XAIReadyHandler | null = null;
30	  private isConfigured = false;
31	
32	  constructor(config: XAIClientConfig) {
33	    this.config = config;
34	  }
35	
36	  /**
37	   * Connect to XAI API
38	   */
39	  async connect(): Promise<void> {
40	    return new Promise((resolve, reject) => {
41	      const { apiKey, apiUrl, sessionId } = this.config;
42	
43	      console.log(`[${sessionId}] 🔌 Connecting to XAI API: ${apiUrl}`);
44	
45	      try {
46	        this.ws = new WebSocket(apiUrl, {
47	          headers: {
48	            Authorization: `Bearer ${apiKey}`,
49	            "Content-Type": "application/json",
50	          },
51	        });
52	
53	        this.ws.on("open", () => {
54	          console.log(`[${sessionId}] ✅ Connected to XAI API`);
55	          resolve();
56	        });
57	
58	        this.ws.on("message", (data: WebSocket.Data) => {
59	          this.handleMessage(data);
60	        });
61	
62	        this.ws.on("error", (error) => {
63	          console.error(`[${sessionId}] ❌ XAI WebSocket error:`, error);
64	          if (this.errorHandler) {
65	            this.errorHandler(error as Error);
66	          }
67	          reject(error);
68	        });
69	
70	        this.ws.on("close", (code, reason) => {
71	          console.log(
72	            `[${sessionId}] ❌ XAI WebSocket closed - Code: ${code}, Reason: ${reason.toString() || "No reason"}`
73	          );
74	          if (this.closeHandler) {
75	            this.closeHandler(code, reason.toString());
76	          }
77	        });
78	      } catch (error) {
79	        console.error(`[${sessionId}] ❌ Failed to create XAI WebSocket:`, error);
80	        reject(error);
81	      }
82	    });
83	  }
84	
85	  /**
86	   * Handle incoming messages from XAI API
87	   */
88	  private handleMessage(data: WebSocket.Data): void {
89	    try {
90	      const message = JSON.parse(data.toString()) as XAIMessage;
91	      const eventType = message.type;
92	      const { sessionId } = this.config;
93	
94	      // Log non-audio events
95	      if (
96	        eventType !== "response.output_audio.delta" &&
97	        eventType !== "input_audio_buffer.append"
98	      ) {
99	        console.log(`[${sessionId}] 📥 XAI → Server: ${eventType}`);
100	
101	        // Log full details for session.updated and error events
102	        if (eventType === "session.updated") {
103	          console.log(`[${sessionId}] 🔧 DEBUG: session.updated details:`, JSON.stringify(message, null, 2));
104	
105	          // After session.updated is confirmed, send initial greeting
106	          console.log(`[${sessionId}] ✅ Session configuration confirmed, sending initial greeting...`);
107	          this.sendMessage({ type: "input_audio_buffer.commit" });
108	          this.sendMessage({
109	            type: "conversation.item.create",
110	            item: {
111	              type: "message",
112	              role: "user",
113	              content: [
114	                {
115	                  type: "input_text",
116	                  text: "Greet me briefly.",
117	                },
118	              ],
119	            },
120	          });
121	          this.sendMessage({ type: "response.create" });
122	          console.log(`[${sessionId}] 🎤 XAI ready for voice interaction`);
123	
124	          // Notify client that it's safe to start sending audio
125	          if (this.onReady) {
126	            this.onReady();
127	          }
128	        }
129	      }
130	
131	      // Handle conversation.created - configure session
132	      if (eventType === "conversation.created" && !this.isConfigured) {
133	        this.configureSession();
134	      }
135	
136	      // Forward message to handler
137	      if (this.messageHandler) {
138	        this.messageHandler(message);
139	      }
140	
141	      // Handle errors
142	      if (eventType === "error") {
143	        const error = (message as any).error || {};
144	        console.error(`[${sessionId}] ❌ XAI API Error:`, error);
145	        console.error(`[${sessionId}] 🔧 DEBUG: Full error message:`, JSON.stringify(message, null, 2));
146	      }
147	    } catch (error) {
148	      console.error(`[${this.config.sessionId}] ❌ Error processing XAI message:`, error);
149	    }
150	  }
151	
152	  /**
153	   * Configure the XAI session
154	   */
155	  private configureSession(): void {
156	    const { sessionId, voice, instructions, sampleRate } = this.config;
157	
158	    console.log(`[${sessionId}] ⚙️  Configuring XAI session with ${sampleRate}Hz audio...`);
159	
160	    // Send session configuration with dynamic sample rate
161	    const sessionConfig = {
162	      type: "session.update",
163	      session: {
164	        instructions,
165	        voice,
166	        audio: {
167	          input: {
168	            format: {
169	              type: "audio/pcm",
170	              rate: sampleRate,
171	            },
172	          },
173	          output: {
174	            format: {
175	              type: "audio/pcm",
176	              rate: sampleRate,
177	            },
178	          },
179	        },
180	        turn_detection: {
181	          type: "server_vad",
182	        },
183	      },
184	    };
185	
186	    console.log(`[${sessionId}] 🔧 DEBUG: Sending session config:`, JSON.stringify(sessionConfig, null, 2));
187	    this.sendMessage(sessionConfig);
188	    console.log(`[${sessionId}] ⚙️  Waiting for session.updated confirmation...`);
189	
190	    // NOTE: Initial greeting will be sent after session.updated is received
191	    // This prevents mixing audio frame rates (sending audio before config is applied)
192	    this.isConfigured = true;
193	  }
194	
195	  /**
196	   * Send a message to XAI API
197	   */
198	  sendMessage(message: XAIMessage): void {
199	    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
200	      console.error(
201	        `[${this.config.sessionId}] ❌ Cannot send message - WebSocket not open`
202	      );
203	      return;
204	    }
205	
206	    try {
207	      this.ws.send(JSON.stringify(message));
208	
209	      // Log non-audio events
210	      if (message.type !== "input_audio_buffer.append") {
211	        console.log(`[${this.config.sessionId}] 📤 Server → XAI: ${message.type}`);
212	      }
213	    } catch (error) {
214	      console.error(
215	        `[${this.config.sessionId}] ❌ Error sending message to XAI:`,
216	        error
217	      );
218	    }
219	  }
220	
221	  /**
222	   * Set message handler
223	   */
224	  onMessage(handler: XAIMessageHandler): void {
225	    this.messageHandler = handler;
226	  }
227	
228	  /**
229	   * Set error handler
230	   */
231	  onError(handler: XAIErrorHandler): void {
232	    this.errorHandler = handler;
233	  }
234	
235	  /**
236	   * Set close handler
237	   */
238	  onClose(handler: XAICloseHandler): void {
239	    this.closeHandler = handler;
240	  }
241	
242	  /**
243	   * Set ready handler (called when XAI session is configured and ready for audio)
244	   */
245	  setReadyHandler(handler: XAIReadyHandler): void {
246	    this.onReady = handler;
247	  }
248	
249	  /**
250	   * Close the connection
251	   */
252	  close(): void {
253	    if (this.ws) {
254	      this.ws.close();
255	      this.ws = null;
256	    }
257	  }
258	
259	  /**
260	   * Check if connected
261	   */
262	  isConnected(): boolean {
263	    return this.ws !== null && this.ws.readyState === WebSocket.OPEN;
264	  }
265	}
