196	          sourceRef.current = source;
197	          const proc = ctx.createScriptProcessor(4096, 1, 1);
198	          procRef.current = proc;
199	          proc.onaudioprocess = (e) => {
200	            const input = e.inputBuffer.getChannelData(0);
201	            inputRmsRef.current = mutedRef.current ? 0 : calculateRms(input);
202	            if (mutedRef.current) return;
203	            pending.push(new Float32Array(input));
204	            total += input.length;
205	            while (total >= chunkSize) {
206	              const chunk = new Float32Array(chunkSize);
207	              let offset = 0;
208	              while (offset < chunkSize && pending.length > 0) {
209	                const buf = pending[0];
210	                const need = chunkSize - offset;
211	                if (buf.length <= need) {
212	                  chunk.set(buf, offset);
213	                  offset += buf.length;
214	                  total -= buf.length;
215	                  pending.shift();
216	                } else {
217	                  chunk.set(buf.subarray(0, need), offset);
218	                  pending[0] = buf.subarray(need);
219	                  offset += need;
220	                  total -= need;
221	                }
222	              }
223	              send({ type: "input_audio_buffer.append", audio: float32ToPcm16Base64(chunk) });
224	            }
225	          };
226	          source.connect(proc);
227	          // Required in some browsers for the callback to fire; the processor
228	          // writes no output, so this does not echo the mic to the speakers.
229	          proc.connect(ctx.destination);
230	        } catch {
231	          fail("— microphone permission denied —");
232	        }
233	      };
234	
235	      // ── transcript helpers ──────────────────────────────────────────────
236	      const pushAgentDelta = (delta: string) => {
237	        agentBufRef.current += delta;
238	        const text = agentBufRef.current;
239	        setCaption(text);
240	        setTurns((prev) => {
241	          const id = agentTurnIdRef.current;
242	          if (id) return prev.map((t) => (t.id === id ? { ...t, text } : t));
243	          const newId = `x${turnSeqRef.current++}`;
244	          agentTurnIdRef.current = newId;
245	          return [...prev, { id: newId, who: "agent", text, live: true }];
246	        });
247	      };
248	      const finalizeAgent = () => {
249	        const id = agentTurnIdRef.current;
250	        if (id) setTurns((prev) => prev.map((t) => (t.id === id ? { ...t, live: false } : t)));
251	        agentTurnIdRef.current = null;
252	        agentBufRef.current = "";
253	      };
254	      const pushUser = (text: string) => {
255	        if (!text) return;
256	        setTurns((prev) => [...prev, { id: `x${turnSeqRef.current++}`, who: "user", text }]);
257	        setCaption(text);
258	      };
259	
260	      // 3) Resolve the active persona's agent config, then open the WS
261	      //    (token rides the subprotocol since browsers can't set WS headers).
262	      const agent = resolveXaiAgent(personaRef.current?.id);
263	      const ws = new WebSocket(`${REALTIME_BASE}?model=${encodeURIComponent(agent.model)}`, [
264	        `xai-client-secret.${token}`,
265	      ]);
266	      wsRef.current = ws;
267	
268	      const configure = () => {
269	        if (configuredRef.current) return;
270	        configuredRef.current = true;
271	        send({
272	          type: "session.update",
273	          session: {
274	            instructions: agent.instructions,
275	            voice: agent.voice,
276	            audio: {
277	              input: { format: { type: "audio/pcm", rate } },
278	              output: { format: { type: "audio/pcm", rate } },
279	            },
280	            turn_detection: agent.turnDetection,
281	            tools: agent.tools,
282	          },
283	        });
284	      };
285	
286	      ws.onmessage = (event) => {
287	        let msg: XaiEvent;
288	        try {
289	          msg = JSON.parse(typeof event.data === "string" ? event.data : "") as XaiEvent;
290	        } catch {
291	          return;
292	        }
293	        switch (msg.type) {
294	          case "conversation.created":
295	          case "session.created":
296	            configure();
297	            break;
298	          case "session.updated": {
299	            void startCapture();
300	            setCallState("listening");
301	            setCaption("listening…");
302	            // Prompt an opening line so the agent speaks first.
303	            send({
304	              type: "conversation.item.create",
305	              item: {
306	                type: "message",
307	                role: "user",
308	                content: [{ type: "input_text", text: agent.firstMessage }],
309	              },
310	            });
311	            send({ type: "response.create" });
312	            break;
313	          }
314	          case "response.output_audio.delta":
315	            if (msg.delta) {
316	              playbackRef.current?.enqueue(base64Pcm16ToFloat32(msg.delta));
317	              if (stateRef.current !== "interrupted") setCallState("speaking");
318	            }
319	            break;
320	          case "response.output_audio_transcript.delta":
321	            if (msg.delta) pushAgentDelta(msg.delta);
322	            break;
323	          case "response.done":
324	            finalizeAgent();
325	            if (stateRef.current === "speaking") setCallState("listening");
326	            break;
327	          case "input_audio_buffer.speech_started":
328	            // Server VAD detected the user — barge-in: stop the agent audio.
329	            playbackRef.current?.stop();
330	            finalizeAgent();
331	            setCallState("interrupted");
332	            if (interruptTimerRef.current) clearTimeout(interruptTimerRef.current);
333	            interruptTimerRef.current = setTimeout(() => setCallState("listening"), 600);
334	            break;
335	          case "input_audio_buffer.committed":
336	          case "input_audio_buffer.speech_stopped":
337	            if (stateRef.current === "interrupted") setCallState("listening");
338	            break;
339	          case "conversation.item.added":
340	          case "conversation.item.created": {
341	            const item = msg.item;
342	            if (item?.role === "user") {
343	              const t = item.content?.find((c) => c.transcript || c.text);
344	              if (t) pushUser((t.transcript ?? t.text ?? "").trim());
345	            }
346	            break;
347	          }
348	          case "error":
349	            // Surface but don't kill — a fatal error will also close the socket.
350	            setCaption(`— ${msg.error?.message ?? "xAI error"} —`);
351	            break;
352	          default:
353	            break;
354	        }
355	      };
356	
357	      ws.onerror = () => {
358	        if (endedRef.current) return;
359	        endedRef.current = true;
360	        teardown();
361	        setCallState("ended");
362	        setCaption("— connection error —");
363	      };
364	
365	      ws.onclose = () => {
366	        if (endedRef.current) return;
367	        endedRef.current = true;
368	        teardown();
369	        setCallState("ended");
370	        setCaption("— call ended —");
371	      };
372	    })();
373	  }, [send, teardown]);
374	
375	  const stop = useCallback(() => {
376	    endedRef.current = true;
377	    teardown();
378	    setCallState("ended");
379	    setCaption("— call ended —");
380	  }, [teardown]);
381	
382	  const interrupt = useCallback(() => {
383	    if (stateRef.current !== "speaking") return;
384	    playbackRef.current?.stop();
385	    setCallState("interrupted");
386	    if (interruptTimerRef.current) clearTimeout(interruptTimerRef.current);
387	    interruptTimerRef.current = setTimeout(() => setCallState("listening"), 600);
388	  }, []);
389	
390	  const setMuted = useCallback((muted: boolean) => {
391	    mutedRef.current = muted;
392	    if (muted) inputRmsRef.current = 0;
393	  }, []);
394	
395	  const getInputVolume = useCallback(() => Math.min(1, inputRmsRef.current * VOL_GAIN), []);
396	  const getOutputVolume = useCallback(
397	    () => Math.min(1, (playbackRef.current?.level ?? 0) * VOL_GAIN),
398	    [],
399	  );
400	
401	  // Hang up + reset if the provider is switched away from xAI mid-session.
402	  useEffect(() => {
403	    if (active) return;
404	    if (stateRef.current !== "idle") {
405	      endedRef.current = true;
406	      teardown();
407	      setCallState("idle");
408	      setTurns([]);
409	      setCaption("press CALL to begin");
410	    }
411	  }, [active, teardown]);
412	
413	  // Cleanup on unmount.
414	  useEffect(() => () => teardown(), [teardown]);
415	
416	  return {
417	    callState,
418	    turns,
419	    caption,
420	    start,
421	    stop,
422	    interrupt,
423	    setMuted,
424	    getInputVolume,
425	    getOutputVolume,
426	  };
427	}
