1	// Framework-free Web Audio helpers for the xAI Grok voice engine.
2	//
3	// xAI's realtime API exchanges raw PCM16 little-endian audio as base64 strings
4	// over the WebSocket (no codec). We capture mic Float32 frames, convert to
5	// PCM16, and base64-encode for `input_audio_buffer.append`; inbound
6	// `response.output_audio.delta` chunks are the reverse. Sample rate is the
7	// browser's native AudioContext rate end-to-end — we advertise it to xAI in
8	// `session.update`, so no resampling is needed (mirrors the xai-cookbook).
9	
10	/** Float32 [-1,1] → PCM16 → base64. */
11	export function float32ToPcm16Base64(float32: Float32Array): string {
12	  const pcm16 = new Int16Array(float32.length);
13	  for (let i = 0; i < float32.length; i++) {
14	    const s = Math.max(-1, Math.min(1, float32[i]));
15	    pcm16[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
16	  }
17	  return arrayBufferToBase64(pcm16.buffer);
18	}
19	
20	/** base64 PCM16 → Float32 [-1,1]. */
21	export function base64Pcm16ToFloat32(base64: string): Float32Array {
22	  const binary = atob(base64);
23	  const bytes = new Uint8Array(binary.length);
24	  for (let i = 0; i < binary.length; i++) {
25	    bytes[i] = binary.charCodeAt(i);
26	  }
27	  const pcm16 = new Int16Array(bytes.buffer);
28	  const float32 = new Float32Array(pcm16.length);
29	  for (let i = 0; i < pcm16.length; i++) {
30	    float32[i] = pcm16[i] / (pcm16[i] < 0 ? 0x8000 : 0x7fff);
31	  }
32	  return float32;
33	}
34	
35	function arrayBufferToBase64(buffer: ArrayBuffer): string {
36	  const bytes = new Uint8Array(buffer);
37	  let binary = "";
38	  // Chunk to stay well under the argument-count limit of String.fromCharCode.
39	  const CHUNK = 0x8000;
40	  for (let i = 0; i < bytes.byteLength; i += CHUNK) {
41	    binary += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
42	  }
43	  return btoa(binary);
44	}
45	
46	/** Root-mean-square level of a frame, ~0..1. */
47	export function calculateRms(float32: Float32Array): number {
48	  let sum = 0;
49	  for (let i = 0; i < float32.length; i++) sum += float32[i] * float32[i];
50	  return Math.sqrt(sum / float32.length);
51	}
52	
53	/**
54	 * Gap-less playback of streamed PCM16 chunks via chained AudioBufferSourceNodes.
55	 * `stop()` clears the queue + kills the current source for barge-in. `level`
56	 * exposes the currently-playing chunk's RMS so the orb can react to TTS output.
57	 */
58	export class PlaybackQueue {
59	  private ctx: AudioContext;
60	  private queue: Float32Array[] = [];
61	  private playing = false;
62	  private current: AudioBufferSourceNode | null = null;
63	  private _level = 0;
64	
65	  constructor(ctx: AudioContext) {
66	    this.ctx = ctx;
67	  }
68	
69	  enqueue(chunk: Float32Array): void {
70	    this.queue.push(chunk);
71	    if (!this.playing) {
72	      this.playing = true;
73	      this.playNext();
74	    }
75	  }
76	
77	  private playNext(): void {
78	    const chunk = this.queue.shift();
79	    if (!chunk) {
80	      this.playing = false;
81	      this.current = null;
82	      this._level = 0;
83	      return;
84	    }
85	    const buffer = this.ctx.createBuffer(1, chunk.length, this.ctx.sampleRate);
86	    buffer.getChannelData(0).set(chunk);
87	    const source = this.ctx.createBufferSource();
88	    source.buffer = buffer;
89	    source.connect(this.ctx.destination);
90	    this.current = source;
91	    this._level = calculateRms(chunk);
92	    source.onended = () => {
93	      if (this.current === source) this.current = null;
94	      this.playNext();
95	    };
96	    source.start();
97	  }
98	
99	  /** Barge-in: stop now and drop anything queued. */
100	  stop(): void {
101	    if (this.current) {
102	      try {
103	        this.current.stop();
104	        this.current.disconnect();
105	      } catch {
106	        // already stopped
107	      }
108	      this.current = null;
109	    }
110	    this.queue = [];
111	    this.playing = false;
112	    this._level = 0;
113	  }
114	
115	  get level(): number {
116	    return this._level;
117	  }
118	
119	  get isPlaying(): boolean {
120	    return this.playing;
121	  }
122	}
