218	      const deviceList = await navigator.mediaDevices.enumerateDevices();
219	
220	      const audioInputs = deviceList
221	        .filter((device) => device.kind === "audioinput")
222	        .map((device) => {
223	          let cleanLabel = device.label || `Microphone ${device.deviceId.slice(0, 8)}`;
224	          cleanLabel = cleanLabel.replace(/\s*\([^)]*\)/g, "").trim();
225	
226	          return {
227	            deviceId: device.deviceId,
228	            label: cleanLabel,
229	            groupId: device.groupId,
230	          };
231	        });
232	
233	      setDevices(audioInputs);
234	      setHasPermission(true);
235	    } catch (err) {
236	      setError(err instanceof Error ? err.message : "Failed to get audio devices");
237	      console.error("Error getting audio devices:", err);
238	    } finally {
239	      setLoading(false);
240	    }
241	  }, [loading]);
242	
243	  useEffect(() => {
244	    loadDevicesWithoutPermission();
245	  }, [loadDevicesWithoutPermission]);
246	
247	  useEffect(() => {
248	    const handleDeviceChange = () => {
249	      if (hasPermission) {
250	        loadDevicesWithPermission();
251	      } else {
252	        loadDevicesWithoutPermission();
253	      }
254	    };
255	
256	    navigator.mediaDevices.addEventListener("devicechange", handleDeviceChange);
257	
258	    return () => {
259	      navigator.mediaDevices.removeEventListener("devicechange", handleDeviceChange);
260	    };
261	  }, [hasPermission, loadDevicesWithPermission, loadDevicesWithoutPermission]);
262	
263	  return {
264	    devices,
265	    loading,
266	    error,
267	    hasPermission,
268	    loadDevices: loadDevicesWithPermission,
269	  };
270	}
